import { kebab } from "./names.ts";
import {
  buttonHeights,
  type Density,
  defaultDensity,
  densities,
  fonts,
  fontWeights,
  layout,
  motion,
  radius,
  type Theme,
  themes,
  typeScale,
} from "./tokens.ts";

type Declaration = readonly [name: string, value: string];

/** The generated stylesheet; apps import it as `@ogcloud/tokens/tokens.css`. */
export const stylesheetUrl = new URL("./generated/tokens.css", import.meta.url);

const HEADER =
  "/* Generated by @ogcloud/tokens from src/tokens.ts (D-0216). `mise run gen:tokens` refreshes it; do not edit. */";

const GENERIC_FAMILIES = new Set([
  "ui-sans-serif",
  "system-ui",
  "sans-serif",
  "ui-monospace",
  "monospace",
]);

const px = (value: number) => `${value}px`;

function block(
  selector: string,
  declarations: readonly Declaration[],
  indent = "",
): string {
  const body = declarations
    .map(([name, value]) => `${indent}  ${name}: ${value};`)
    .join("\n");
  return `${indent}${selector} {\n${body}\n${indent}}`;
}

function themeDeclarations(
  scheme: "light" | "dark",
  theme: Theme,
): Declaration[] {
  return [
    ["color-scheme", scheme],
    ...Object.entries(theme.colours).map(
      ([key, value]): Declaration => [`--og-${kebab(key)}`, value],
    ),
    ...Object.entries(theme.shadows).map(
      ([key, value]): Declaration => [`--og-shadow-${key}`, value],
    ),
  ];
}

function densityDeclarations(density: Density): Declaration[] {
  return [
    ["--og-row-height", px(density.rowHeight)],
    ["--og-control-height", px(density.controlHeight)],
    ["--og-nav-item-height", px(density.navItemHeight)],
    ["--og-table-font-size", px(density.tableFontSize)],
    ["--og-table-line-height", px(density.tableLineHeight)],
  ];
}

function fontStack(stack: readonly string[]): string {
  return stack
    .map((family) => (GENERIC_FAMILIES.has(family) ? family : `"${family}"`))
    .join(", ");
}

// Tailwind's defaults go, so only OgCloud's tokens exist as utilities (AGENTS.md §13).
function staticTheme(): Declaration[] {
  const type = Object.entries(typeScale).flatMap(
    ([key, style]): Declaration[] => {
      const name = kebab(key);
      return [
        [`--text-${name}`, px(style.size)],
        [`--text-${name}--line-height`, px(style.lineHeight)],
        [`--text-${name}--font-weight`, String(style.weight)],
        ...(style.tracking === undefined
          ? []
          : [[`--text-${name}--letter-spacing`, style.tracking] as const]),
      ];
    },
  );
  const [x1, y1, x2, y2] = motion.easing.standard;
  return [
    ["--color-*", "initial"],
    ["--shadow-*", "initial"],
    ["--radius-*", "initial"],
    ["--font-*", "initial"],
    ["--font-weight-*", "initial"],
    ["--text-*", "initial"],
    ["--ease-*", "initial"],
    ...Object.entries(fonts).map(
      ([name, stack]): Declaration => [`--font-${name}`, fontStack(stack)],
    ),
    ...Object.entries(fontWeights).map(
      ([name, weight]): Declaration => [
        `--font-weight-${name}`,
        String(weight),
      ],
    ),
    ...Object.entries(radius).map(
      ([name, value]): Declaration => [`--radius-${name}`, px(value)],
    ),
    ...type,
    ["--ease-standard", `cubic-bezier(${x1}, ${y1}, ${x2}, ${y2})`],
    ["--spacing-button-sm", px(buttonHeights.sm)],
    ["--spacing-button-lg", px(buttonHeights.lg)],
    ["--spacing-sidebar", px(layout.sidebarWidth)],
    ["--spacing-header", px(layout.headerHeight)],
    ["--container-form", px(layout.formWidth)],
    ["--container-branded", px(layout.brandedWidth)],
    ["--container-setup", px(layout.setupWidth)],
    ["--container-colour-picker", px(layout.colourPickerWidth)],
    ["--container-aside-min", px(layout.asideMinWidth)],
    ["--container-aside", px(layout.asideWidth)],
    ["--container-side-min", px(layout.sideMinWidth)],
    ["--container-number-field", px(layout.numberFieldWidth)],
    ["--container-toast", px(layout.toastMaxWidth)],
  ];
}

// Utilities point at the runtime variables, so a theme or density switch restyles without a rebuild.
function inlineTheme(theme: Theme): Declaration[] {
  return [
    ...Object.keys(theme.colours).map(
      (key): Declaration => [
        `--color-${kebab(key)}`,
        `var(--og-${kebab(key)})`,
      ],
    ),
    ...Object.keys(theme.shadows).map(
      (key): Declaration => [`--shadow-${key}`, `var(--og-shadow-${key})`],
    ),
    ["--spacing-row", "var(--og-row-height)"],
    ["--spacing-control", "var(--og-control-height)"],
    ["--spacing-nav-item", "var(--og-nav-item-height)"],
    ["--text-table", "var(--og-table-font-size)"],
    ["--text-table--line-height", "var(--og-table-line-height)"],
  ];
}

function fixedDeclarations(): Declaration[] {
  return [
    ...Object.entries(motion.durationMs).map(
      ([name, ms]): Declaration => [`--og-duration-${name}`, `${ms}ms`],
    ),
    ["--og-sidebar-inset", px(layout.sidebarInset)],
  ];
}

/** The whole stylesheet: Tailwind's theme, light and compact by default, dark by OS or choice, comfortable by choice. */
export function renderCss(): string {
  const dark = themeDeclarations("dark", themes.dark);
  const sections = [
    HEADER,
    block("@theme", staticTheme()),
    block("@theme inline", inlineTheme(themes.light)),
    block(":root", [
      ...themeDeclarations("light", themes.light),
      ...densityDeclarations(densities[defaultDensity]),
      ...fixedDeclarations(),
    ]),
    `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme="light"])', dark, "  ")}\n}`,
    block(':root[data-theme="dark"]', dark),
    block(
      ':root[data-density="comfortable"]',
      densityDeclarations(densities.comfortable),
    ),
  ];
  return `${sections.join("\n\n")}\n`;
}
